import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/physical-geography/temperature-and-climate/","title":"CH1.5 气温、气候与寒暑 | 英语","lang":"zh-CN","frontmatter":{"title":"CH1.5 气温、气候与寒暑","createTime":"2026-11-18T09:50:00.000Z","permalink":"/english/vocabulary/physical-geography/temperature-and-climate/"},"readingTime":{"minutes":31.74,"words":9522},"git":{"createdTime":1795010783000},"filePathRelative":"english/vocabulary/physical-geography/5.temperature-and-climate.md","headers":[],"bulletin":false}`),a={name:`5.temperature-and-climate.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="celsius" tabindex="-1"><a class="header-anchor" href="#celsius"><span>Celsius</span></a></h2><p class="vc-meta"><strong>/ˈselsiəs/</strong> · noun · 名词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>摄氏度（的），摄氏温标（的）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>degrees Celsius</td><td>摄氏度</td></tr><tr><td>20 degrees Celsius</td><td>20 摄氏度</td></tr><tr><td>on the Celsius scale</td><td>按摄氏温标</td></tr><tr><td>minus five Celsius</td><td>零下五度</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows average temperatures rising from 12 to 15 degrees Celsius.</p><blockquote><p>该图表显示平均气温从 12 摄氏度上升到 15 摄氏度。</p></blockquote><p><strong>Writing Task 2</strong> Limiting warming to 1.5 degrees Celsius requires rapid and deep cuts in emissions.</p><blockquote><p>要把升温控制在 1.5 摄氏度以内，需要迅速而大幅地削减排放。</p></blockquote><p><strong>Speaking</strong> It was thirty-five degrees Celsius yesterday — too hot to do anything.</p><blockquote><p>昨天三十五摄氏度，热得什么都干不了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>centigrade</td><td>摄氏度</td><td>旧称，现多被 Celsius 取代</td></tr><tr><td>Fahrenheit</td><td>华氏度</td><td>英美日常仍用，科学不用</td></tr><tr><td>Kelvin</td><td>开尔文</td><td>科学计量，无&quot;度&quot;字</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 源自瑞典天文学家 Anders <strong>Celsius</strong>（1742 年提出百分温标）</li><li><strong>Family:</strong> Celsius 摄氏度 / centigrade 百分度 / Fahrenheit 华氏度 / Kelvin 开尔文</li><li><strong>Memory Tip:</strong> 人名命名，首字母永远大写。centigrade 是旧称（意为&quot;百分度&quot;），现在学术与媒体基本统一用 Celsius。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>必须大写：Celsius，不写 <s>celsius</s>。</li><li>语序是 20 degrees Celsius 或 20°C，不说 <s>20 Celsius degrees</s>。</li><li>口语常省略：It&#39;s 20 degrees.</li></ul></div><div class="vocab-card"><h2 id="temperature" tabindex="-1"><a class="header-anchor" href="#temperature"><span>Temperature</span></a></h2><p class="vc-meta"><strong>/ˈtemprətʃə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>温度，气温</li><li>体温；（身体的）发热</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>average temperature</td><td>平均气温</td></tr><tr><td>a rise in temperature</td><td>气温上升</td></tr><tr><td>room temperature</td><td>室温</td></tr><tr><td>body temperature</td><td>体温</td></tr><tr><td>temperatures drop</td><td>气温下降</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows average monthly temperatures in three cities.</p><blockquote><p>该图表显示了三个城市的月平均气温。</p></blockquote><p><strong>Writing Task 2</strong> Global average temperatures have risen by about 1.1 degrees since pre-industrial times.</p><blockquote><p>自工业化前以来，全球平均气温已上升约 1.1 度。</p></blockquote><p><strong>Speaking</strong> The temperature dropped to minus five overnight.</p><blockquote><p>一夜之间气温降到了零下五度。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>heat</td><td>热度</td><td>指热的程度或来源，非读数</td></tr><tr><td>warmth</td><td>温暖</td><td>主观感受，带褒义</td></tr><tr><td>climate</td><td>气候</td><td>长期平均，非瞬时读数</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>temperatura</em>（适度的状态）← <em>temperare</em>（调和、混合）</li><li><strong>Family:</strong> temperature 温度 / temper 脾气 / temperate 温带的；有节制的 / temperament 性情</li><li><strong>Memory Tip:</strong> 词根是&quot;调和&quot;，所以 temper（脾气）、temperate（温和的）都是一家。图表题三件套：a rise / fall / average in temperature。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：temperatures rose（多地或多时）。</li><li>&quot;气温上升&quot;用 a rise in temperature，别写 <s>temperature rises up</s>。</li><li>口语报温度：The temperature is 20 degrees.</li></ul></div><div class="vocab-card"><h2 id="forecast" tabindex="-1"><a class="header-anchor" href="#forecast"><span>Forecast</span></a></h2><p class="vc-meta"><strong>/ˈfɔːkɑːst/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：预报，预测</li><li>动词：预报，预测</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>weather forecast</td><td>天气预报</td></tr><tr><td>rain is forecast</td><td>预报有雨</td></tr><tr><td>economic forecast</td><td>经济预测</td></tr><tr><td>as forecast</td><td>如预报所言</td></tr><tr><td>a gloomy forecast</td><td>悲观的预测</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the forecast with the actual figures for 2024.</p><blockquote><p>该图表把预测值与 2024 年的实际数据作了比较。</p></blockquote><p><strong>Writing Task 2</strong> Forecasts of sea-level rise have been revised upwards repeatedly.</p><blockquote><p>关于海平面上升的预测已被多次上调。</p></blockquote><p><strong>Speaking</strong> The forecast says rain by the weekend, so let&#39;s go tomorrow.</p><blockquote><p>预报说周末有雨，那我们明天去吧。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>prediction</td><td>预测</td><td>最通用，无&quot;提前&quot;含义</td></tr><tr><td>projection</td><td>推算</td><td>基于数据的长期推算</td></tr><tr><td>outlook</td><td>展望</td><td>偏趋势判断，语气较软</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>fore-</em>（预先）+ <em>cast</em>（投、抛）→ 提前抛出判断</li><li><strong>Family:</strong> forecast 预报 / forecaster 预报员 / forecastle 船首楼 / broadcast 广播</li><li><strong>Memory Tip:</strong> fore（前）+ cast（抛）= 提前把结论抛出去。同族的 broadcast 原义是&quot;广泛撒种&quot;，后来变成&quot;广播&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>过去式通常仍写 forecast（也可 forecasted）。</li><li>weather forecast 前不加 the。</li><li>&quot;预报有雨&quot;说 rain is forecast，不用 <s>the forecast says to rain</s>。</li></ul></div><div class="vocab-card"><h2 id="snowy" tabindex="-1"><a class="header-anchor" href="#snowy"><span>Snowy</span></a></h2><p class="vc-meta"><strong>/ˈsnəʊi/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>下雪的，多雪的</li><li>雪白的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>snowy mountains</td><td>雪山</td></tr><tr><td>a snowy winter</td><td>多雪的冬天</td></tr><tr><td>snowy peaks</td><td>雪峰</td></tr><tr><td>snowy owl</td><td>雪鸮</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows snowy peaks rising above the treeline.</p><blockquote><p>照片显示了高出林线的雪峰。</p></blockquote><p><strong>Writing Task 2</strong> Snowy winters are becoming shorter across much of the northern hemisphere.</p><blockquote><p>在北半球大部分地区，多雪的冬季正变得越来越短。</p></blockquote><p><strong>Speaking</strong> We had a snowy Christmas for the first time in years.</p><blockquote><p>我们过了多年来第一个下雪的圣诞节。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>snow-covered</td><td>覆雪的</td><td>强调被雪盖住的状态</td></tr><tr><td>snowbound</td><td>被雪困住的</td><td>强调交通、出行受阻</td></tr><tr><td>white</td><td>白的</td><td>泛称，无气象含义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>snow</em>（雪）+ <em>-y</em>（充满……的）</li><li><strong>Family:</strong> snow 雪 / snowy 多雪的 / snowfall 降雪量 / snowstorm 暴风雪 / snowdrift 雪堆</li><li><strong>Memory Tip:</strong> -y 后缀的天气形容词一组记：snowy 多雪、rainy 多雨、windy 多风、sunny 多晴、cloudy 多云。地图题里几乎都能用上。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;被雪覆盖的&quot;是 snow-covered，不是 <s>snowy-covered</s>。</li><li>snowy 形容&quot;这个冬天雪多&quot;，不形容&quot;正在下雪&quot;（那是 it&#39;s snowing）。</li><li>拼写保留 y：snowy，不是 <s>snowey</s>。</li></ul></div><div class="vocab-card"><h2 id="frost" tabindex="-1"><a class="header-anchor" href="#frost"><span>Frost</span></a></h2><p class="vc-meta"><strong>/frɒst/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：霜；霜冻（气象现象）</li><li>动词：结霜；（给蛋糕）撒糖霜</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a hard frost</td><td>严重霜冻</td></tr><tr><td>ground frost</td><td>地面霜冻</td></tr><tr><td>frost damage</td><td>霜冻损害</td></tr><tr><td>frostbite</td><td>冻伤</td></tr><tr><td>late frost</td><td>晚霜</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows areas at risk of late frost in spring.</p><blockquote><p>该地图显示了春季有晚霜风险的地区。</p></blockquote><p><strong>Writing Task 2</strong> A single late frost can destroy an entire season&#39;s fruit crop.</p><blockquote><p>一场晚霜就能毁掉一整季的水果收成。</p></blockquote><p><strong>Speaking</strong> There was a thick frost on the car this morning.</p><blockquote><p>今天早上车上结了一层厚霜。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>hoarfrost</td><td>白霜</td><td>指结晶状的白色霜，更具体</td></tr><tr><td>rime</td><td>雾凇</td><td>由雾滴冻结形成</td></tr><tr><td>freeze</td><td>冰冻</td><td>指事件，不是霜本身</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>frost</em>，与 <em>freeze</em> 同出日耳曼语 <em>freusan</em></li><li><strong>Family:</strong> frost 霜 / frosty 结霜的；冷淡的 / frostbite 冻伤 / defrost 除霜</li><li><strong>Memory Tip:</strong> frost 与 freeze 同根，一个是&quot;霜&quot;（名词），一个是&quot;结冰&quot;（动作）。frosty 引申为&quot;冷淡的&quot;：a frosty reception 冷遇。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数不可数皆可：a hard frost / heavy frost。</li><li>frostbite 是&quot;冻伤&quot;，不是&quot;霜咬&quot;；动词是 frostbite 的过去分词 frostbitten。</li><li>拼写 frost，别与 forest（森林）混。</li></ul></div><div class="vocab-card"><h2 id="hail" tabindex="-1"><a class="header-anchor" href="#hail"><span>Hail</span></a></h2><p class="vc-meta"><strong>/heɪl/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：冰雹；（雹子般的）一阵</li><li>动词：招呼（出租车）；称赞为（hail as）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a hail storm</td><td>雹暴</td></tr><tr><td>hailstones</td><td>冰雹粒</td></tr><tr><td>hail a taxi</td><td>招手叫出租车</td></tr><tr><td>be hailed as</td><td>被誉为</td></tr><tr><td>hail from</td><td>来自（某地）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the area affected by the June hail storm.</p><blockquote><p>该地图显示了六月雹暴影响的区域。</p></blockquote><p><strong>Writing Task 2</strong> Hail can strip a field in minutes, which makes it a serious risk for farmers.</p><blockquote><p>冰雹能在几分钟内打光一片田，对农民来说是严重风险。</p></blockquote><p><strong>Speaking</strong> We got caught in a hail storm — the stones were the size of peas.</p><blockquote><p>我们遇上雹暴，雹子有豌豆那么大。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sleet</td><td>雨夹雪</td><td>雨雪混合，非冰粒</td></tr><tr><td>graupel</td><td>软雹</td><td>气象学术语，松软不透明</td></tr><tr><td>pellets</td><td>颗粒</td><td>泛称，需上下文说明是冰</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 名词源自古英语 <em>hægel</em>（冰雹）；动词&quot;招呼&quot;源自古诺斯语 <em>heill</em>（健康）——两个 hail 同形异源</li><li><strong>Family:</strong> hail 冰雹；招呼 / hailstorm 雹暴 / hailstone 冰雹粒 / hail from 来自</li><li><strong>Memory Tip:</strong> 两个 hail 要分开记：冰雹那个和 freeze 一伙；&quot;招呼、致敬&quot;那个与 heal、whole 同源（heill = 完好）。hail from 就是&quot;出身于&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>冰雹义不可数：不说 <s>hails</s>。</li><li>hail a taxi 是&quot;招手拦车&quot;，不是&quot;喊车&quot;。</li><li>be hailed as 后接名词：was hailed as a hero。</li></ul></div><div class="vocab-card"><h2 id="thaw" tabindex="-1"><a class="header-anchor" href="#thaw"><span>Thaw</span></a></h2><p class="vc-meta"><strong>/θɔː/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：（冰、雪、冻食）融化，解冻</li><li>名词：解冻期；（关系的）缓和</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the spring thaw</td><td>春季解冻</td></tr><tr><td>thaw out</td><td>解冻，化开</td></tr><tr><td>a thaw in relations</td><td>关系缓和</td></tr><tr><td>leave to thaw</td><td>放着解冻</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows river flow peaking during the spring thaw.</p><blockquote><p>该图表显示河流流量在春季解冻时达到峰值。</p></blockquote><p><strong>Writing Task 2</strong> An earlier spring thaw can cause flooding in March and water shortages by August.</p><blockquote><p>春季提前解冻可能造成三月洪涝、八月缺水。</p></blockquote><p><strong>Speaking</strong> Leave the chicken out to thaw for a couple of hours.</p><blockquote><p>把鸡肉拿出来放两小时解冻。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>melt</td><td>融化</td><td>更通用，冰、雪、金属都能用</td></tr><tr><td>defrost</td><td>除霜</td><td>多指冰箱、车窗除霜</td></tr><tr><td>soften</td><td>缓和</td><td>只对应抽象义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>thawian</em>（融化）</li><li><strong>Family:</strong> thaw 解冻 / thawing 融化 / thaw out 化开 / freeze-thaw cycle 冻融循环</li><li><strong>Memory Tip:</strong> thaw 是&quot;冻的东西回软&quot;，melt 是&quot;固体变液体&quot;。所以冷冻食品用 thaw，冰淇淋化了用 melt。a thaw in relations 是外交上的&quot;关系解冻&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>食物解冻用 thaw，不用 <s>melt</s>。</li><li>the spring thaw 要加 the，指每年那段时期。</li><li>拼写 th- 开头，读音 /θɔː/，别读成 /tɔː/。</li></ul></div><div class="vocab-card"><h2 id="chill" tabindex="-1"><a class="header-anchor" href="#chill"><span>Chill</span></a></h2><p class="vc-meta"><strong>/tʃɪl/</strong> · noun · 名词 / verb · 动词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：寒意；（一阵）发冷</li><li>动词：使变冷，冷藏；使害怕</li><li>形容词：寒冷的；放松的（口语）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a chill in the air</td><td>空气中有寒意</td></tr><tr><td>wind chill</td><td>风寒</td></tr><tr><td>catch a chill</td><td>着凉</td></tr><tr><td>chill out</td><td>放松</td></tr><tr><td>chilled to the bone</td><td>冷到骨头里</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares air temperature with wind chill at three sites.</p><blockquote><p>该图表比较了三个地点的气温与风寒指数。</p></blockquote><p><strong>Writing Task 2</strong> Wind chill makes sub-zero temperatures feel far colder than the thermometer suggests.</p><blockquote><p>风寒效应使零下的温度体感远比温度计读数更冷。</p></blockquote><p><strong>Speaking</strong> There&#39;s a real chill in the air tonight — winter&#39;s coming.</p><blockquote><p>今晚空气里真有股寒意，冬天要来了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>cold</td><td>冷</td><td>客观温度，最中性</td></tr><tr><td>frost</td><td>霜冻</td><td>指具体气象现象</td></tr><tr><td>coolness</td><td>凉意</td><td>程度轻，多形容宜人的凉</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>cele</em>（寒冷），与 <em>cold</em>、<em>cool</em> 同源</li><li><strong>Family:</strong> chill 寒意 / chilly 微冷的 / chilled 冰镇的 / chill out 放松</li><li><strong>Memory Tip:</strong> chill 是&quot;让人一激灵的冷&quot;，比 cold 更主观。wind chill 是&quot;风寒指数&quot;；chill out 则是&quot;放松&quot;——从身体冷到心理松，很形象。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词是 chilly：a chilly morning，不用 <s>a chill morning</s>（除非 chill 作定语，如 chill wind）。</li><li>catch a chill 是固定搭配，介词不换。</li><li>wind chill 前不加 the。</li></ul></div><div class="vocab-card"><h2 id="freeze" tabindex="-1"><a class="header-anchor" href="#freeze"><span>Freeze</span></a></h2><p class="vc-meta"><strong>/friːz/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：结冰，冻结；冻僵；突然停住</li><li>名词：冻结（工资、价格）；冰冻期</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>freeze over</td><td>（水面）结冰</td></tr><tr><td>freeze to death</td><td>冻死</td></tr><tr><td>a wage freeze</td><td>工资冻结</td></tr><tr><td>freeze up</td><td>冻住；卡住</td></tr><tr><td>deep freeze</td><td>深冻；停滞</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows the number of days the lake surface froze each winter.</p><blockquote><p>该图显示了每年冬天湖面结冰的天数。</p></blockquote><p><strong>Writing Task 2</strong> A wage freeze was introduced to bring inflation under control.</p><blockquote><p>为控制通胀，政府实行了工资冻结。</p></blockquote><p><strong>Speaking</strong> The pipes froze last night, so we had no water this morning.</p><blockquote><p>昨晚水管冻住了，今天早上没水用。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>ice over</td><td>结冰</td><td>专指水面或路面结冰</td></tr><tr><td>chill</td><td>冷冻</td><td>强调降温，不一定是结冰</td></tr><tr><td>halt</td><td>停止</td><td>只对应抽象&quot;冻结&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>frēosan</em>，与 <em>frost</em> 同源</li><li><strong>Family:</strong> freeze 结冰 / frozen 冰冻的 / freezer 冷冻柜 / freezing 极冷的 / frost 霜</li><li><strong>Memory Tip:</strong> 不规则变化 freeze - froze - frozen。口语里 freezing 就是&quot;冷死了&quot;：It&#39;s freezing out there!</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>过去式 froze、过去分词 frozen，不是 <s>freezed</s>。</li><li>&quot;工资冻结&quot;是 a wage freeze，用 wage 更常见。</li><li>形容词形式是 frozen（frozen food 冷冻食品），不是 <s>freezed food</s>。</li></ul></div><div class="vocab-card"><h2 id="frigid" tabindex="-1"><a class="header-anchor" href="#frigid"><span>Frigid</span></a></h2><p class="vc-meta"><strong>/ˈfrɪdʒɪd/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>严寒的，冰冷的（气候、水、空气）</li><li>冷淡的（态度）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>frigid air</td><td>极冷的空气</td></tr><tr><td>frigid waters</td><td>冰冷的水域</td></tr><tr><td>the frigid zone</td><td>寒带</td></tr><tr><td>a frigid reception</td><td>冷淡的接待</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows frigid air moving south from the Arctic.</p><blockquote><p>该地图显示了来自北极的冷空气南下。</p></blockquote><p><strong>Writing Task 2</strong> Frigid conditions make outdoor work dangerous without proper clothing.</p><blockquote><p>在严寒条件下，没有合适的衣物，户外作业十分危险。</p></blockquote><p><strong>Speaking</strong> It was frigid out there — minus twenty before the wind.</p><blockquote><p>外面冷得刺骨，不算风都零下二十度。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>freezing</td><td>冰冷的</td><td>口语常用，程度比 frigid 轻</td></tr><tr><td>icy</td><td>冰冷的</td><td>强调结冰、湿滑</td></tr><tr><td>arctic</td><td>极寒的</td><td>带&quot;北极般&quot;的比喻</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>frigidus</em>（冷的）← <em>frigere</em>（变冷）</li><li><strong>Family:</strong> frigid 严寒的 / frigidity 寒冷 / refrigerator 冰箱 / fridge 冰箱 / refrigerate 冷藏</li><li><strong>Memory Tip:</strong> frig- = 冷。refrigerator 字面就是&quot;致冷的东西&quot;，口语缩成 fridge。the frigid zone 是地理上的&quot;寒带&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>语气比 cold 强得多，指&quot;严寒&quot;，别用来形容凉爽天气。</li><li>形容人时&quot;冷淡&quot;义可解，但另有旧义易引歧义，正式文本中慎用。</li><li>拼写 fri-gid，注意中间是 g。</li></ul></div><div class="vocab-card"><h2 id="tremble" tabindex="-1"><a class="header-anchor" href="#tremble"><span>Tremble</span></a></h2><p class="vc-meta"><strong>/ˈtrembl/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>颤抖，发抖（因恐惧、虚弱、寒冷）</li><li>（声音）发颤；（大地）轻微震动</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>tremble with fear</td><td>吓得发抖</td></tr><tr><td>tremble at the thought</td><td>一想到就发抖</td></tr><tr><td>a trembling voice</td><td>颤抖的声音</td></tr><tr><td>tremble slightly</td><td>微微颤动</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows ground movement recorded as the volcano trembled before the eruption.</p><blockquote><p>该图显示了火山在喷发前颤动时记录到的地面运动。</p></blockquote><p><strong>Writing Task 2</strong> Investors watched the market tremble as the news spread.</p><blockquote><p>消息传开后，投资者看着市场剧烈震荡。</p></blockquote><p><strong>Speaking</strong> My hands were trembling so much that I could barely sign my name.</p><blockquote><p>我手抖得几乎签不上名字。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>shake</td><td>摇动</td><td>最通用，可及物</td></tr><tr><td>shiver</td><td>发抖</td><td>多因寒冷或恐惧</td></tr><tr><td>quiver</td><td>轻微颤动</td><td>幅度小，多形容声音、嘴唇</td></tr><tr><td>shudder</td><td>战栗</td><td>带厌恶或强烈恐惧</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>tremulus</em>（颤抖的）→ <em>tremere</em>（发抖）</li><li><strong>Family:</strong> tremble 颤抖 / tremor 轻微地震；战栗 / tremulous 颤抖的（书面）</li><li><strong>Memory Tip:</strong> tremulus = 抖。地质学里 volcanic tremor 专指&quot;火山颤动&quot;；tremendous 原义是&quot;令人发抖的&quot;，如今只剩&quot;巨大的&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不及物动词：不说 <s>tremble sth</s>。</li><li>与 shiver 分工：tremble 可因恐惧、虚弱、寒冷，shiver 多因冷或怕。</li><li>拼写 -ble 结尾，不是 <s>-bel</s>。</li></ul></div><div class="vocab-card"><h2 id="shiver" tabindex="-1"><a class="header-anchor" href="#shiver"><span>Shiver</span></a></h2><p class="vc-meta"><strong>/ˈʃɪvə(r)/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>（因寒冷、恐惧）发抖，哆嗦</li><li>名词：颤抖，寒颤</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>shiver with cold</td><td>冷得发抖</td></tr><tr><td>send shivers down one&#39;s spine</td><td>令人毛骨悚然</td></tr><tr><td>a shiver ran through</td><td>一阵寒颤掠过</td></tr><tr><td>shiver in the wind</td><td>在风里发抖</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows wind chill — the point at which exposed skin begins to shiver.</p><blockquote><p>该图表显示了风寒指数，即裸露皮肤开始发抖的临界点。</p></blockquote><p><strong>Writing Task 2</strong> A shiver ran through the crowd as the ground shook.</p><blockquote><p>地面晃动时，人群中掠过一阵战栗。</p></blockquote><p><strong>Speaking</strong> I was shivering so hard that my teeth were chattering.</p><blockquote><p>我抖得牙齿都在打颤。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>tremble</td><td>颤抖</td><td>原因更广，含虚弱</td></tr><tr><td>shudder</td><td>战栗</td><td>强烈厌恶或恐惧</td></tr><tr><td>quake</td><td>发抖；震动</td><td>幅度大，也可指地震</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>chiveren</em>，词源不明，一般认为与&quot;牙齿打颤&quot;的拟声有关</li><li><strong>Family:</strong> shiver 发抖 / shivery 发抖的 / shivers 寒颤</li><li><strong>Memory Tip:</strong> shiver 几乎总跟&quot;冷&quot;和&quot;怕&quot;绑在一起。send shivers down one&#39;s spine 是&quot;令人毛骨悚然&quot;，写作里很好用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 with：shiver with cold / fear。</li><li>名词可数：a shiver / shivers。</li><li>别与 quiver（轻颤）混，shiver 幅度更明显。</li></ul></div><div class="vocab-card"><h2 id="climate" tabindex="-1"><a class="header-anchor" href="#climate"><span>Climate</span></a></h2><p class="vc-meta"><strong>/ˈklaɪmət/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>气候（长期天气状况）</li><li>氛围，形势（the current climate）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>climate change</td><td>气候变化</td></tr><tr><td>a mild climate</td><td>温和的气候</td></tr><tr><td>a tropical climate</td><td>热带气候</td></tr><tr><td>climatic conditions</td><td>气候条件</td></tr><tr><td>in the current climate</td><td>在当前形势下</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the different climate zones across the continent.</p><blockquote><p>该地图显示该大陆上的各个气候带。</p></blockquote><p><strong>Writing Task 2</strong> Climate is what you expect over decades; weather is what you get this week.</p><blockquote><p>气候是几十年间的常态，天气是这一周的实际情况。</p></blockquote><p><strong>Speaking</strong> I couldn&#39;t live in that climate — far too humid for me.</p><blockquote><p>那种气候我住不下去，对我来说太潮了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>weather</td><td>天气</td><td>短期、具体，逐日变化</td></tr><tr><td>conditions</td><td>条件，状况</td><td>泛称，可指天气或环境</td></tr><tr><td>atmosphere</td><td>氛围</td><td>只对应抽象义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>klima</em>（倾斜）——古人按太阳照射角度划分气候带</li><li><strong>Family:</strong> climate 气候 / climatic 气候的 / acclimatise 适应水土 / clime 气候（文学）</li><li><strong>Memory Tip:</strong> klima = 倾斜。阳光入射角不同，就有了不同的气候带。这个命名逻辑从希腊一直用到今天。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a mild climate / different climates。</li><li>climate change 前不加 the；climate 的形容词是 climatic，不是 <s>climatical</s>。</li><li>与 weather 别混：climate 讲长期，weather 讲某天。</li></ul></div><div class="vocab-card"><h2 id="weather" tabindex="-1"><a class="header-anchor" href="#weather"><span>Weather</span></a></h2><p class="vc-meta"><strong>/ˈweðə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>天气（某时某地的具体气象状况）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>weather forecast</td><td>天气预报</td></tr><tr><td>bad weather</td><td>恶劣天气</td></tr><tr><td>weather conditions</td><td>天气状况</td></tr><tr><td>weather permitting</td><td>天气允许的话</td></tr><tr><td>under the weather</td><td>身体不适</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows average weather conditions in three cities over a year.</p><blockquote><p>该图表显示三个城市一年中的平均天气状况。</p></blockquote><p><strong>Writing Task 2</strong> Extreme weather is becoming more frequent as the climate warms.</p><blockquote><p>随着气候变暖，极端天气越来越频繁。</p></blockquote><p><strong>Speaking</strong> The weather&#39;s been awful all week — rain every single day.</p><blockquote><p>这周天气糟透了，天天下雨。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>climate</td><td>气候</td><td>长期平均，非逐日</td></tr><tr><td>conditions</td><td>天气状况</td><td>正式，多用于报告</td></tr><tr><td>the elements</td><td>风雨等恶劣天气</td><td>文学化表达</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>weder</em>（天气、风暴），与 <em>wind</em> 同源</li><li><strong>Family:</strong> weather 天气 / weather-beaten 饱经风霜的 / weatherproof 防风雨的</li><li><strong>Memory Tip:</strong> weather 不可数，所以只能说 good weather，不能说 <s>a good weather</s>。习语 under the weather 是&quot;身体不太舒服&quot;，与天气无关。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>a weather</s> 或 <s>weathers</s>。</li><li>weather forecast 前不带 the。</li><li>under the weather 是&quot;不舒服&quot;，别按字面理解。</li></ul></div><div class="vocab-card"><h2 id="meteorology" tabindex="-1"><a class="header-anchor" href="#meteorology"><span>Meteorology</span></a></h2><p class="vc-meta"><strong>/ˌmiːtiəˈrɒlədʒi/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>气象学；（某一地区的）气象</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>meteorological data</td><td>气象数据</td></tr><tr><td>a meteorological station</td><td>气象站</td></tr><tr><td>the science of meteorology</td><td>气象科学</td></tr><tr><td>the Met Office</td><td>英国气象局</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart is based on meteorological data collected over thirty years.</p><blockquote><p>该图表依据的是三十年间的气象数据。</p></blockquote><p><strong>Writing Task 2</strong> Meteorology has greatly improved short-term forecasting, but long-range prediction remains uncertain.</p><blockquote><p>气象学极大改善了短期预报，但长期预测仍不确定。</p></blockquote><p><strong>Speaking</strong> My uncle studied meteorology and now works for the national weather service.</p><blockquote><p>我叔叔学的是气象学，现在在国家气象部门工作。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>climatology</td><td>气候学</td><td>研究长期气候，非逐日天气</td></tr><tr><td>forecasting</td><td>预报</td><td>指业务行为，非学科</td></tr><tr><td>atmospheric science</td><td>大气科学</td><td>范围更大，含化学与物理</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>meteōron</em>（高空之物）+ <em>-logia</em>（学科）→ 研究高空现象的学问</li><li><strong>Family:</strong> meteorology 气象学 / meteorological 气象的 / meteorologist 气象学家 / meteor 流星</li><li><strong>Memory Tip:</strong> meteōron 泛指&quot;天上的东西&quot;，包括流星，所以 meteor（流星）与 meteorology 同源。别以为它只研究流星。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词是 meteorological，不用 <s>meteorologic</s>。</li><li>学科名不可数，不加 a。</li><li>与 climatology 区分：前者管天气，后者管气候。</li></ul></div><div class="vocab-card"><h2 id="mild" tabindex="-1"><a class="header-anchor" href="#mild"><span>Mild</span></a></h2><p class="vc-meta"><strong>/maɪld/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>（气候）温和的，不严寒的</li><li>（味道、病情、批评）轻微的，不严重的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a mild climate</td><td>温和的气候</td></tr><tr><td>a mild winter</td><td>暖冬</td></tr><tr><td>mild symptoms</td><td>轻微症状</td></tr><tr><td>to put it mildly</td><td>说得客气一点</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows that winters have become milder since the 1980s.</p><blockquote><p>该图显示自 20 世纪 80 年代以来冬季变得更为温和。</p></blockquote><p><strong>Writing Task 2</strong> A milder climate may lengthen the growing season, but it also lets pests survive the winter.</p><blockquote><p>更温和的气候可能延长生长季，但也让害虫得以越冬。</p></blockquote><p><strong>Speaking</strong> It&#39;s been a mild winter — I haven&#39;t worn a coat once.</p><blockquote><p>今年是暖冬，我一次大衣都没穿过。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>moderate</td><td>适中的</td><td>强调不过度，非温度专属</td></tr><tr><td>gentle</td><td>温和的</td><td>多形容动作、坡度</td></tr><tr><td>temperate</td><td>温带的</td><td>气候带术语，更学术</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>milde</em>（温和、宽容）</li><li><strong>Family:</strong> mild 温和的 / mildly 轻微地 / mildness 温和 / milder 更温和的</li><li><strong>Memory Tip:</strong> 一条线从人延伸到物：a mild man（性情温和）→ a mild winter（冬天不冷）→ mild curry（不怎么辣）。核心都是&quot;不强烈&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>比较级 milder，不用 <s>more mild</s>。</li><li>mildly 常表&quot;稍微&quot;：mildly surprised（略感意外）。</li><li>mild 不等于 warm：mild 强调&quot;不严酷&quot;，warm 强调&quot;温度高&quot;。</li></ul></div><div class="vocab-card"><h2 id="heating" tabindex="-1"><a class="header-anchor" href="#heating"><span>Heating</span></a></h2><p class="vc-meta"><strong>/ˈhiːtɪŋ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>供暖，暖气（设备与系统）</li><li>加热，升温</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>central heating</td><td>集中供暖</td></tr><tr><td>the heating bill</td><td>取暖费</td></tr><tr><td>global heating</td><td>全球升温</td></tr><tr><td>heating system</td><td>供暖系统</td></tr><tr><td>heating up</td><td>变热，升温</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares household spending on heating and electricity.</p><blockquote><p>该图表比较了家庭在供暖与用电上的支出。</p></blockquote><p><strong>Writing Task 2</strong> &quot;Global heating&quot; is arguably a more accurate term than &quot;global warming&quot; for what is now happening.</p><blockquote><p>就当下发生的情况而言，&quot;全球升温&quot;比&quot;全球变暖&quot;或许是更准确的说法。</p></blockquote><p><strong>Speaking</strong> The heating&#39;s broken again, so we&#39;re all wearing jumpers indoors.</p><blockquote><p>暖气又坏了，我们在屋里都穿着毛衣。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>warming</td><td>变暖</td><td>指过程，不指设备</td></tr><tr><td>heat</td><td>暖气（美式）</td><td>美式常说 turn up the heat</td></tr><tr><td>insulation</td><td>保温</td><td>减少热损失，非供热</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>heat</em>（热）+ <em>-ing</em></li><li><strong>Family:</strong> heating 供暖 / heat 热 / heater 加热器 / heated 激烈的（争论）</li><li><strong>Memory Tip:</strong> 英式 the heating 就是&quot;暖气&quot;，美式说 the heat。气候语境里 global heating 是近年替代 global warming 的新说法，强调&quot;持续加热&quot;而非单纯&quot;变暖&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>a heating</s>；说 turn on / turn up the heating。</li><li>英式 heating、美式 heat，同一篇文章里保持一致。</li><li>heating up 是动词短语，别当名词用。</li></ul></div><div class="vocab-card"><h2 id="moderate" tabindex="-1"><a class="header-anchor" href="#moderate"><span>Moderate</span></a></h2><p class="vc-meta"><strong>/ˈmɒdərət/</strong> · adj · 形容词（动词读 /ˈmɒdəreɪt/）</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：适度的，中等的；温和的（气候、观点）</li><li>动词：缓和，使减轻；主持（讨论）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a moderate climate</td><td>温和的气候</td></tr><tr><td>moderate growth</td><td>适度增长</td></tr><tr><td>moderate exercise</td><td>适量运动</td></tr><tr><td>in moderation</td><td>适度地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows moderate growth in the first half of the period, followed by a sharp rise.</p><blockquote><p>该图显示前半段为适度增长，随后急剧上升。</p></blockquote><p><strong>Writing Task 2</strong> Moderate warming may benefit some crops, but the gains disappear beyond two degrees.</p><blockquote><p>适度升温可能有利于某些作物，但超过两度后这些好处就会消失。</p></blockquote><p><strong>Speaking</strong> I try to drink coffee in moderation — one cup a day.</p><blockquote><p>我尽量适量喝咖啡，一天一杯。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>mild</td><td>温和的</td><td>强调不严酷，多形容气候</td></tr><tr><td>modest</td><td>不大的</td><td>强调规模小，带谦逊意味</td></tr><tr><td>temperate</td><td>有节制的</td><td>更书面，也指温带</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>moderare</em>（节制、调节）← <em>modus</em>（尺度）</li><li><strong>Family:</strong> moderate 适度的 / moderation 适度 / moderator 调解者；主持人 / modest 谦虚的</li><li><strong>Memory Tip:</strong> modus = 尺度，moderate 就是&quot;在尺度之内&quot;。重音随词性走：形容词在前，动词在后。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>重音：形容词 /ˈmɒdərət/，动词 /ˈmɒdəreɪt/。</li><li>与 modest 区分：moderate growth 适度增长，a modest increase 小幅增长。</li><li>in moderation 是固定短语，别写 <s>with moderation</s>。</li></ul></div><div class="vocab-card"><h2 id="warm" tabindex="-1"><a class="header-anchor" href="#warm"><span>Warm</span></a></h2><p class="vc-meta"><strong>/wɔːm/</strong> · adj · 形容词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：温暖的；热情的</li><li>动词：使变暖，加热（warm up）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>warm weather</td><td>温暖的天气</td></tr><tr><td>a warm welcome</td><td>热情的欢迎</td></tr><tr><td>global warming</td><td>全球变暖</td></tr><tr><td>warm up</td><td>变暖；热身</td></tr><tr><td>a warm front</td><td>暖锋</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows warm ocean currents moving north along the coast.</p><blockquote><p>该地图显示了沿海南北上的暖流。</p></blockquote><p><strong>Writing Task 2</strong> Warmer winters allow disease-carrying insects to survive in regions that were once too cold for them.</p><blockquote><p>更暖的冬季让带病昆虫得以在曾经对它们而言过冷的地区存活。</p></blockquote><p><strong>Speaking</strong> It&#39;s warm enough for a T-shirt today — strange for November.</p><blockquote><p>今天暖和得能穿 T 恤，对十一月来说很奇怪。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>mild</td><td>温和的</td><td>强调不冷，非温度高</td></tr><tr><td>hot</td><td>热的</td><td>程度更强，常带不适感</td></tr><tr><td>balmy</td><td>温暖宜人的</td><td>文学化，多形容夜晚、微风</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>wearm</em></li><li><strong>Family:</strong> warm 温暖的 / warmth 温暖；热情 / warmly 热情地 / warming 变暖</li><li><strong>Memory Tip:</strong> 三条线：温度（warm water）、态度（a warm welcome）、动作（warm up 热身）。核心都是&quot;热起来&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>比较级 warmer，不双写 m。</li><li>动词短语是 warm up，不是 <s>warm</s>。</li><li>global warming 是固定搭配，不加 the。</li></ul></div><div class="vocab-card"><h2 id="thermal" tabindex="-1"><a class="header-anchor" href="#thermal"><span>Thermal</span></a></h2><p class="vc-meta"><strong>/ˈθɜːml/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>热的，热量的</li><li>保暖的（衣物）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>thermal energy</td><td>热能</td></tr><tr><td>a thermal power station</td><td>火力发电厂</td></tr><tr><td>thermal insulation</td><td>隔热，保温</td></tr><tr><td>thermal springs</td><td>温泉</td></tr><tr><td>thermal underwear</td><td>保暖内衣</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how a thermal power station converts heat into electricity.</p><blockquote><p>该示意图显示了火力发电厂如何把热能转化为电能。</p></blockquote><p><strong>Writing Task 2</strong> Better thermal insulation could cut household energy use by a third.</p><blockquote><p>更好的保温措施能把家庭能耗削减三分之一。</p></blockquote><p><strong>Speaking</strong> These trousers have a thermal lining — perfect for a cold snap.</p><blockquote><p>这条裤子有保暖内衬，寒潮来正合适。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>geothermal</td><td>地热的</td><td>特指来自地球内部的热</td></tr><tr><td>warm</td><td>温暖的</td><td>日常形容词，非技术词</td></tr><tr><td>heat-related</td><td>与热有关的</td><td>描述性说法，非术语</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>thermē</em>（热）→ <em>thermalis</em></li><li><strong>Family:</strong> thermal 热的 / thermometer 温度计 / thermostat 恒温器 / thermos 保温瓶 / geothermal 地热的</li><li><strong>Memory Tip:</strong> therm- = 热，一个词根串起一串：thermometer 温度计、thermostat 恒温器、thermos 保温瓶、geothermal 地热的。看到 therm 就想&quot;热&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>thermal 是形容词，不能当名词用。</li><li>&quot;温泉&quot;说 thermal springs 或 hot springs，不说 <s>thermal water</s>。</li><li>拼写 ther-mal，注意 -mal 结尾。</li></ul></div><div class="vocab-card"><h2 id="tropics" tabindex="-1"><a class="header-anchor" href="#tropics"><span>Tropics</span></a></h2><p class="vc-meta"><strong>/ˈtrɒpɪks/</strong> · noun · 名词（复数）</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>热带（南北回归线之间的地带）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>in the tropics</td><td>在热带</td></tr><tr><td>a tropical climate</td><td>热带气候</td></tr><tr><td>tropical rainforest</td><td>热带雨林</td></tr><tr><td>subtropical</td><td>亚热带的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows that rainforests are concentrated in the tropics.</p><blockquote><p>该地图显示雨林集中分布在热带。</p></blockquote><p><strong>Writing Task 2</strong> Species in the tropics are adapted to stable temperatures and are therefore especially vulnerable to change.</p><blockquote><p>热带的物种适应了稳定的温度，因此对变化尤为脆弱。</p></blockquote><p><strong>Speaking</strong> I spent two years in the tropics and never got used to the humidity.</p><blockquote><p>我在热带待了两年，始终没适应那种潮湿。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>the Torrid Zone</td><td>热带</td><td>旧称，地理教科书偶见</td></tr><tr><td>equatorial region</td><td>赤道地区</td><td>范围更窄，仅赤道附近</td></tr><tr><td>tropical belt</td><td>热带带</td><td>学术表述</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>tropē</em>（转向）——太阳在南北回归线之间&quot;转身&quot;，夹在中间的地带即热带</li><li><strong>Family:</strong> tropics 热带 / tropical 热带的 / subtropical 亚热带的 / the Tropic of Cancer 北回归线</li><li><strong>Memory Tip:</strong> tropē = 转向。太阳到夏至、冬至就&quot;掉头&quot;，那两条线叫回归线（tropics of Cancer / Capricorn），夹在中间的就是 the tropics。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>加 the：in the tropics。</li><li>形容词是 tropical：tropical climate，不用 <s>tropic climate</s>。</li><li>拼写 trop-ics，注意只有一个 p。</li></ul></div><div class="vocab-card"><h2 id="arid" tabindex="-1"><a class="header-anchor" href="#arid"><span>Arid</span></a></h2><p class="vc-meta"><strong>/ˈærɪd/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>干旱的（降水量远低于蒸发量）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an arid region</td><td>干旱地区</td></tr><tr><td>an arid climate</td><td>干旱气候</td></tr><tr><td>semi-arid</td><td>半干旱的</td></tr><tr><td>arid land</td><td>干旱土地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows that farming is confined to the narrow strip between the arid interior and the coast.</p><blockquote><p>该地图显示农业仅限于干旱内陆与海岸之间的狭长地带。</p></blockquote><p><strong>Writing Task 2</strong> Arid regions are expanding as rainfall patterns shift towards the poles.</p><blockquote><p>随着降水格局向两极移动，干旱区正在扩大。</p></blockquote><p><strong>Speaking</strong> Nothing grows there — it&#39;s completely arid for hundreds of kilometres.</p><blockquote><p>那儿什么都长不出来，几百公里全是旱地。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>dry</td><td>干的</td><td>日常用词，程度不明</td></tr><tr><td>parched</td><td>焦干的</td><td>强调极度缺水，带画面感</td></tr><tr><td>barren</td><td>贫瘠的</td><td>强调无法生长，非降水量</td></tr><tr><td>desert</td><td>荒漠的</td><td>指地貌类型</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>arere</em>（干燥）→ <em>aridus</em></li><li><strong>Family:</strong> arid 干旱的 / aridity 干旱度 / semi-arid 半干旱的</li><li><strong>Memory Tip:</strong> arid 是气候学术语，判据是&quot;降水量 &lt; 蒸发量&quot;。barren 讲&quot;长不出东西&quot;，arid 讲&quot;水不够&quot;——两个词常一起出现但侧重不同。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 ar-id，别写成 <s>arried</s>。</li><li>semi-arid 带连字符。</li><li>学术写作固定用 arid region / arid climate，不用 <s>dry climate</s>（程度不明）。</li></ul></div><div class="vocab-card"><h2 id="moist" tabindex="-1"><a class="header-anchor" href="#moist"><span>Moist</span></a></h2><p class="vc-meta"><strong>/mɔɪst/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>微湿的，湿润的（褒义或中性）</li><li>（眼睛）湿润的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>moist air</td><td>湿润的空气</td></tr><tr><td>moist soil</td><td>湿润的土壤</td></tr><tr><td>keep the soil moist</td><td>保持土壤湿润</td></tr><tr><td>moist eyes</td><td>湿润的眼睛</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows moist air rising, cooling and forming clouds.</p><blockquote><p>该示意图显示了湿润空气上升、冷却并成云的过程。</p></blockquote><p><strong>Writing Task 2</strong> Warm air holds more water vapour than cool air, so moist air rises and releases heat as it condenses.</p><blockquote><p>暖空气比冷空气能容纳更多水汽，因此湿空气上升，凝结时释放热量。</p></blockquote><p><strong>Speaking</strong> Keep the soil moist but not soaking — that&#39;s the trick with these plants.</p><blockquote><p>让土保持湿润但别积水，养这种植物的诀窍就在这儿。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>damp</td><td>潮湿的</td><td>带贬义，指不该湿的地方湿了</td></tr><tr><td>humid</td><td>湿热的</td><td>专指空气湿度大，常伴高温</td></tr><tr><td>wet</td><td>湿的</td><td>程度更强，可滴水的状态</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>mucidus</em>（霉湿的）→ 古法语 <em>moiste</em></li><li><strong>Family:</strong> moist 微湿的 / moisture 水分 / moisten 弄湿 / moisturise 保湿</li><li><strong>Memory Tip:</strong> 三个&quot;湿&quot;按褒贬分：moist（微湿，中性偏褒，a moist cake 松软）→ damp（阴冷发霉，贬）→ humid（湿热，说天气）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词是 moisture（水分），不用 <s>moistness</s>。</li><li>形容食物是褒义（moist cake），形容房间会显得奇怪。</li><li>拼写 moi-st，别漏 i。</li></ul></div><div class="vocab-card"><h2 id="damp" tabindex="-1"><a class="header-anchor" href="#damp"><span>Damp</span></a></h2><p class="vc-meta"><strong>/dæmp/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：潮湿的（带阴冷、发霉的意味）</li><li>名词：潮气，湿气</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>damp air</td><td>湿冷的空气</td></tr><tr><td>a damp room</td><td>潮湿的房间</td></tr><tr><td>damp-proof course</td><td>防潮层</td></tr><tr><td>a damp squib</td><td>虎头蛇尾的事</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows a damp, poorly drained field after heavy rain.</p><blockquote><p>照片显示暴雨之后一片湿涝、排水不良的田地。</p></blockquote><p><strong>Writing Task 2</strong> Damp housing is consistently linked to respiratory illness in children.</p><blockquote><p>潮湿的住房一直被认为与儿童呼吸道疾病相关。</p></blockquote><p><strong>Speaking</strong> The flat smells damp — I think there&#39;s a leak somewhere.</p><blockquote><p>这房子有股潮味，我觉得哪儿在漏水。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>moist</td><td>微湿的</td><td>中性偏褒，不带霉味</td></tr><tr><td>humid</td><td>湿热的</td><td>形容空气与天气</td></tr><tr><td>soggy</td><td>湿透的</td><td>程度最强，软塌塌</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中低德语 <em>damp</em>（蒸汽、雾）</li><li><strong>Family:</strong> damp 潮湿的 / dampen 使潮湿；抑制 / dampness 潮气 / damp-proof 防潮的</li><li><strong>Memory Tip:</strong> damp 几乎总带负面联想：潮、冷、霉。dampen 还引申为&quot;抑制情绪、热情&quot;：dampen enthusiasm。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>多作定语：damp air / a damp room，比较级 damper。</li><li>名词 damp 不可数：There&#39;s damp on the wall。</li><li>a damp squib 是习语，指&quot;雷声大雨点小&quot;。</li></ul></div><div class="vocab-card"><h2 id="humid" tabindex="-1"><a class="header-anchor" href="#humid"><span>Humid</span></a></h2><p class="vc-meta"><strong>/ˈhjuːmɪd/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>（空气、天气）湿热的，湿度大的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a humid climate</td><td>湿热气候</td></tr><tr><td>hot and humid</td><td>又热又潮</td></tr><tr><td>humid air</td><td>湿空气</td></tr><tr><td>relative humidity</td><td>相对湿度</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows that humidity peaks during the coastal monsoon months.</p><blockquote><p>该图表显示湿度在沿海季风月份达到峰值。</p></blockquote><p><strong>Writing Task 2</strong> Hot, humid conditions slow physical work and raise the risk of heat stress.</p><blockquote><p>湿热的环境会降低体力劳动效率，并增加热应激风险。</p></blockquote><p><strong>Speaking</strong> It&#39;s not that hot, but it&#39;s so humid that you sweat standing still.</p><blockquote><p>其实不算热，但潮得站着都出汗。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>muggy</td><td>闷热的</td><td>口语，强调不透气</td></tr><tr><td>sticky</td><td>黏腻的</td><td>强调皮肤黏糊感</td></tr><tr><td>sultry</td><td>闷热的</td><td>文学化，多形容夏夜</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>humidus</em>（湿的）← <em>humere</em>（潮湿）</li><li><strong>Family:</strong> humid 湿热的 / humidity 湿度 / humidify 加湿 / dehumidifier 除湿机</li><li><strong>Memory Tip:</strong> humid 专指&quot;空气里的水汽多&quot;，所以几乎总和 hot 搭伴：hot and humid。名词 humidity 是图表题常客，尤其是 relative humidity（相对湿度）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>humid 形容空气或天气，不形容物体（物体用 damp / moist）。</li><li>humidity 不可数，不说 <s>humidities</s>（除非指多处湿度值）。</li><li>拼写 hu-mid，别写成 <s>humide</s>。</li></ul></div><div class="vocab-card"><h2 id="sunshine" tabindex="-1"><a class="header-anchor" href="#sunshine"><span>Sunshine</span></a></h2><p class="vc-meta"><strong>/ˈsʌnʃaɪn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>阳光，日照</li><li>晴天，晴朗天气；（口语）愉快</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>bright sunshine</td><td>阳光明媚</td></tr><tr><td>in the sunshine</td><td>在阳光下</td></tr><tr><td>hours of sunshine</td><td>日照时数</td></tr><tr><td>sunshine hours</td><td>日照时数（图表示例）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares hours of sunshine in three coastal cities.</p><blockquote><p>该图表比较了三个沿海城市的日照时数。</p></blockquote><p><strong>Writing Task 2</strong> More sunshine hours mean higher evaporation and, in turn, heavier irrigation demand.</p><blockquote><p>日照时数增加意味着蒸发更强，进而推高灌溉需求。</p></blockquote><p><strong>Speaking</strong> We sat in the sunshine all afternoon and did nothing at all.</p><blockquote><p>我们在阳光下坐了一下午，什么也没干。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sunlight</td><td>阳光</td><td>强调光线本身，可数性不同</td></tr><tr><td>daylight</td><td>日光</td><td>指白昼的光，非太阳直射</td></tr><tr><td>rays</td><td>光线</td><td>多用于&quot;有害射线&quot;语境</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>sun</em>（太阳）+ <em>shine</em>（照耀）</li><li><strong>Family:</strong> sunshine 阳光 / sunlit 阳光照到的 / sunshiny 晴朗的 / sunscreen 防晒霜</li><li><strong>Memory Tip:</strong> 图表题固定说法是 sunshine hours（日照时数），单位 hours。sunshine 不可数，得靠 hours 来计量。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>a sunshine</s>。</li><li>介词用 in：in the sunshine。</li><li>表&quot;日照时数&quot;用 sunshine hours，不是 <s>sunshine time</s>。</li></ul></div><div class="vocab-card"><h2 id="shade" tabindex="-1"><a class="header-anchor" href="#shade"><span>Shade</span></a></h2><p class="vc-meta"><strong>/ʃeɪd/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：阴凉处；色度，色调；（树）荫</li><li>动词：遮蔽，挡光；使（意义）渐变</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>in the shade</td><td>在阴凉处</td></tr><tr><td>a shade of blue</td><td>一种蓝色调</td></tr><tr><td>shade temperature</td><td>荫温</td></tr><tr><td>provide shade</td><td>提供荫蔽</td></tr><tr><td>shade into</td><td>渐渐变成</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows shade temperature measured beneath tree cover.</p><blockquote><p>该示意图显示了在树荫下测得的荫温。</p></blockquote><p><strong>Writing Task 2</strong> Urban trees provide shade that lowers ground temperatures by several degrees.</p><blockquote><p>城市树木提供的荫蔽能使地表温度降低数度。</p></blockquote><p><strong>Speaking</strong> Let&#39;s find some shade — it&#39;s far too hot out here.</p><blockquote><p>找个阴凉地儿吧，外面太热了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>shadow</td><td>影子</td><td>指投出的暗影，非空间</td></tr><tr><td>shelter</td><td>遮蔽</td><td>泛指挡风遮雨</td></tr><tr><td>cool</td><td>阴凉</td><td>形容温度，非位置</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>sceadu</em>（阴影）</li><li><strong>Family:</strong> shade 阴凉 / shady 阴凉的；可疑的 / shadeless 无遮蔽的 / sunglasses 太阳镜</li><li><strong>Memory Tip:</strong> shade 是&quot;阴凉的空间&quot;（人站进去），shadow 是&quot;投出的影子&quot;（有形无体）。所以是 sit in the shade，不是 sit in the shadow。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 in：in the shade（在阴凉处）。</li><li>shade 可数表色调：various shades of green。</li><li>shady 除&quot;阴凉的&quot;，还指&quot;可疑的&quot;：a shady deal。</li></ul></div><div class="vocab-card"><h2 id="shadow" tabindex="-1"><a class="header-anchor" href="#shadow"><span>Shadow</span></a></h2><p class="vc-meta"><strong>/ˈʃædəʊ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：影子，阴影；（比喻）阴影，威胁</li><li>动词：跟踪，尾随</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>cast a shadow</td><td>投下影子</td></tr><tr><td>in the shadow of</td><td>在……的阴影下</td></tr><tr><td>without a shadow of doubt</td><td>毫无疑问</td></tr><tr><td>shadow cabinet</td><td>影子内阁</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how the length of a shadow changes with the sun&#39;s angle.</p><blockquote><p>该示意图显示了影长如何随太阳角度变化。</p></blockquote><p><strong>Writing Task 2</strong> Cities in the shadow of mountains cool down earlier in the evening.</p><blockquote><p>位于山脉阴影下的城市傍晚降温更早。</p></blockquote><p><strong>Speaking</strong> The tree cast a long shadow across the lawn.</p><blockquote><p>那棵树在草坪上投下长长的影子。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>silhouette</td><td>剪影</td><td>强调轮廓，非暗影</td></tr><tr><td>shade</td><td>阴凉处</td><td>指空间，不是影</td></tr><tr><td>reflection</td><td>倒影</td><td>水面映出的像</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>sceadwe</em>（阴影，shade 的弱化形式）</li><li><strong>Family:</strong> shadow 影子 / shadowy 阴暗的；模糊的 / overshadow 使失色</li><li><strong>Memory Tip:</strong> 三个固定搭配一次记：cast a shadow（投下影子）、in the shadow of（在阴影下）、without a shadow of doubt（毫无疑问）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>动词搭配是 cast a shadow，不用 <s>make a shadow</s>。</li><li>可数：a shadow / long shadows。</li><li>shade（阴凉处）与 shadow（影子）不可互换。</li></ul></div>`,28)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};